/*
 * A210187  Triangle of coefficients of polynomials u(n,x) jointly generated
 *          with A210188; see the Formula section.
 * https://oeis.org/A210187
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   not stated
 * Range:     u8 n <= 24, u16 n <= 59, u32 n <= 59, u64 n <= 59, u128 n <= 59,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  
 *  Formula:  A210187 is the flattened triangle of coefficients of the
 *  polynomials u(n,x) generated by  
 *       u(1,x)=1 ,  v(1,x)=1
 *       u(n,x)=u(n-1,x)+v(n-1,x)+1
 *       v(n,x)=x*u(n-1,x)+(x+1)*v(n-1,x)+1      (n≥2)
 *  The triangle is read row‑wise (constant term first).  
 *  For example the first rows of u(n,x) are:
 *       n=1 : 1
 *       n=2 : 3
 *       n=3 : 2x+6   → coefficients 6,2
 *       n=4 : 2x²+9x+10 → coefficients 10,9,2
 *  Hence a(1)=1, a(2)=3, a(3)=6, a(4)=2, a(5)=10, a(6)=9, …
 */

#include <stddef.h>
#include <stdlib.h>

#if defined(__cplusplus)
#  define ALLOC_SEQ(sz) new seq_t[(sz)]
#  define FREE_SEQ(ptr) delete[] (ptr)
#else
#  define ALLOC_SEQ(sz) ((seq_t*)malloc((sz)*sizeof(seq_t)))
#  define FREE_SEQ(ptr) free((ptr))
#endif

seq_t a(idx_t n)
{
    /* Find the row k that contains the nth coefficient */
    idx_t sum = 0;
    idx_t k   = 0;
    while (sum < n) {
        ++k;
        sum += (k == 1 ? 1 : k - 1);
    }
    /* Number of coefficients before row k */
    idx_t prev = sum - (k == 1 ? 1 : k - 1);
    /* Position in row k (0‑based), constant term is j=0 */
    size_t j = (size_t)(n - prev - 1);

    /* Starting arrays for u(1) and v(1) */
    seq_t *u = ALLOC_SEQ(1);  u[0] = (seq_t)1;
    seq_t *v = ALLOC_SEQ(1);  v[0] = (seq_t)1;
    size_t deg_u = 0, deg_v = 0;

    /* Iterate up to row k */
    for (idx_t cur = 2; cur <= k; ++cur) {
        size_t new_deg_u = (cur >= 2 ? cur - 2 : 0);
        size_t new_deg_v = cur - 1;
        seq_t *new_u = ALLOC_SEQ(new_deg_u + 1);
        seq_t *new_v = ALLOC_SEQ(new_deg_v + 1);

        /* Compute v(cur,x) */
        for (size_t d = 0; d <= new_deg_v; ++d) {
            seq_t s = (seq_t)0;
            if (d >= 1 && d - 1 <= deg_u)
                s += u[d - 1];                 /* x*u(prev) shift */
            if (d >= 1 && d - 1 <= deg_v)
                s += v[d - 1];                 /* x*v(prev) shift */
            if (d <= deg_v)
                s += v[d];                     /* v(prev) */
            if (d == 0)
                s += (seq_t)1;                 /* constant 1 */
            new_v[d] = s;
        }

        /* Compute u(cur,x) */
        for (size_t d = 0; d <= new_deg_u; ++d) {
            seq_t s = (seq_t)0;
            if (d <= deg_u)
                s += u[d];
            if (d <= deg_v)
                s += v[d];
            if (d == 0)
                s += (seq_t)1;                 /* constant 1 */
            new_u[d] = s;
        }

        /* Free old arrays */
        FREE_SEQ(u);
        FREE_SEQ(v);

        /* Prepare for next step */
        u     = new_u;
        v     = new_v;
        deg_u = new_deg_u;
        deg_v = new_deg_v;
    }

    /* The required coefficient is in u[j] */
    seq_t result = u[j];

    /* Clean up */
    FREE_SEQ(u);
    FREE_SEQ(v);

    return result;
}
